(() => {
 const key='day-one-journey-learning-v1',reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const fresh=()=>({step:0,reached:0,done:[],licence:'',age:'',issuer:'',experience:'',earlyIssue:'',interrupted:false,learnerPlace:'',licenceStage:'',applicationStep:0,curriculum:'',stay:'',topic:0,roadPassed:[],mode:'train',ticketSeen:[],cases:{},session:null,checks:[],saved:false,...structuredClone(Object.assign({},...Object.values(jlCustomTracks).map(c=>c.fields)))});
 // Tab order: Healthcare (static) → Transport → Driving → data-driven tracks (Campus, Housing, Daily life).
 const tracks=['transport','driving',...Object.keys(jlCustomTracks)];
 const custom=()=>jlCustomTracks[state.track];
 let state={track:'healthcare',open:false,profile:{country:'',side:'',habit:''},...Object.fromEntries(tracks.map(id=>[id,fresh()]))};
 try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&['healthcare',...tracks].includes(raw.track)){state={...state,...raw,profile:{...state.profile,...raw.profile}};for(const track of tracks){state[track]={...fresh(),...raw[track]};const p=state[track];p.step=Math.max(0,Math.min(5,Number(p.step)||0));p.reached=Math.max(p.step,Math.min(5,Number(p.reached)||0));if(!Array.isArray(p.done)||!Array.isArray(p.roadPassed)||!Array.isArray(p.ticketSeen)||!Array.isArray(p.checks))state[track]=fresh();if(!p.cases||typeof p.cases!=='object'||Array.isArray(p.cases))p.cases={};if(p.session&&(!Object.hasOwn(jlGuides,p.session.id)||!Number.isInteger(p.session.index)||p.session.index<0||p.session.index>=jlGuides[p.session.id].steps.length))p.session=null;jlCustomTracks[track]?.normalise(state[track])}if(!jlCountries.some(c=>c[0]===state.profile.country))state.profile.country=''}}catch{}
 // Journey Tree always opens on Healthcare; progress in every track is kept.
 state.track='healthcare';state.open=false;
 if(state.driving.curriculum!=='licence-v24'){const p=state.driving,map=[0,1,4,4,4,5],checkMap=[0,1,4,5,6];p.step=map[p.step]??0;p.done=[...new Set(p.done.map(i=>map[i]).filter(i=>Number.isInteger(i)))];p.checks=p.checks.map(i=>checkMap[i]).filter(i=>Number.isInteger(i));p.curriculum='licence-v24'}
 let overviewScroll=0;
 const t=(en,zh)=>window.appLanguage==='zh'?zh:en;
 const pair=p=>p?.[window.appLanguage==='zh'?1:0]||'';
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const active=()=>state[state.track];
 const save=()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{}};
 const paths={card:'M3 5h18v14H3ZM3 10h18M6 15h4',phone:'M7 2h10v20H7ZM11 18h2',back:'m15 5-7 7 7 7',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',car:'m4 11 2-6h12l2 6M3 11h18v8H3ZM6 19v2m12-2v2M6 14h2m8 0h2',train:'M6 3h12v14H6ZM6 10h12M8 21l2-4m6 4-2-4M9 14h.01M15 14h.01',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 4h.01',save:'M6 3h12v18l-6-4-6 4Z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z'};
 const svg=name=>`<svg class="jl-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.help}"/></svg>`;
 const flag=id=>jlCountries.some(c=>c[0]===id)&&id!=='OTHER'||id==='AU'?`<img class="jl-flag" src="assets/flags/${id.toLowerCase()}.svg" width="28" height="21" alt="" aria-hidden="true">`:`<span class="jl-flag jl-flag-globe" aria-hidden="true">${svg('globe')}</span>`;
 const button=(label,action,extra='',cls='jl-btn jl-primary')=>`<button class="${cls}" data-jl="${action}" ${extra}>${label}</button>`;
 const applyCountry=()=>{state.profile.side=jlCountrySides[state.profile.country]||'unknown';state.profile.habit=state.profile.country==='CN'?'digital':'card'};
 applyCountry();
 save();
 const country=()=>{const c=jlCountries.find(c=>c[0]===state.profile.country);return c?c[window.appLanguage==='zh'?2:1]:t('Your background','你的背景')};
 const source=(...ids)=>`<details class="jl-source"><summary>${t('Official information','官方信息与依据')}</summary>${[...new Set(ids)].filter(id=>jlSources[id]).map(id=>`<a href="${jlSources[id][1]}" target="_blank" rel="noopener noreferrer">${esc(jlSources[id][0])} ↗</a>`).join('')}<small>${t('Updated 20 Oct 2026','更新于 2026 年 10 月 20 日')}</small></details>`;
 const callout=(title,copy,cls='')=>`<aside class="jl-callout ${cls}"><strong>${title}</strong><p>${copy}</p></aside>`;
 const car=(x,y,color='#1953D9',rotate=0)=>`<g transform="translate(${x} ${y}) rotate(${rotate})"><rect x="-8" y="-15" width="16" height="30" rx="5" fill="${color}"/><rect x="-5" y="-8" width="10" height="7" rx="2" fill="#fff"/><rect x="-5" y="6" width="10" height="4" rx="1" fill="#fff"/></g>`;
 function visual(kind,phase=0){
  let art='',caption=t('Travel situation','出行情境');
  if(kind==='lanes'){
   const side=state.profile.side==='right'?1:0;
   const roads=[0,160].map((x,i)=>{
    const road=`<rect x="${x+35}" y="38" width="90" height="119" rx="10" fill="#DCE2EC"/><path d="M${x+80} 42V151" stroke="white" stroke-width="3" stroke-dasharray="9 7"/>`;
    if(i===0&&state.profile.side==='unknown')return road+`<rect x="43" y="72" width="74" height="48" rx="6" fill="#F1F4F8"/><text x="80" y="101" text-anchor="middle" font-size="11">${t('Local rules','当地规则')}</text>`;
    return road+car(x+(i===0?(side?101:59):59),105,i===0?'#596277':'#1953D9')+car(x+(i===0?(side?59:101):101),83,'#8792A5',180)+`<path d="M${x+(i===0?(side?101:59):59)} 65v-13m-4 4 4-4 4 4" stroke="${i===0?'#596277':'#1953D9'}" fill="none" stroke-width="2"/>`;
   }).join('');
   art=`<rect width="320" height="168" fill="#F1F4F8"/><text x="80" y="23" text-anchor="middle">${esc(country())}</text><text x="240" y="23" text-anchor="middle">Victoria</text>${roads}`;
   caption=t('Driving direction compared with Victoria','对照当地与维州的行车方向');
  }else if(kind==='speed'){
   art=`<rect width="320" height="168" fill="#EDF4EF"/><path d="M87 168 131 19h58l44 149Z" fill="#D7DEE8"/><path d="m160 155 0-123" stroke="white" stroke-width="3" stroke-dasharray="12 9"/><path d="M254 71v74" stroke="#7D8796" stroke-width="4"/><circle cx="254" cy="51" r="30" fill="white" stroke="#C8443A" stroke-width="6"/><text x="254" y="61" text-anchor="middle" font-size="28">40</text>${car(134,119)}<text x="22" y="28">${t('Posted limit','标示限速')}</text>`;
  }else if(kind==='hook'){
   art=`<rect width="320" height="168" fill="#ECF1EE"/><path d="M92 0h72v168H92ZM0 38h320v72H0Z" fill="#D4DCE7"/><path d="M128 0v168M0 74h320" stroke="white" stroke-width="2" stroke-dasharray="8 8"/><path d="M155 0v168" stroke="#8995A8"/><path d="M161 0v168" stroke="#8995A8"/><rect x="97" y="43" width="44" height="27" rx="5" fill="#DDF4E9" stroke="#087452" stroke-dasharray="4 3"/><text x="119" y="60" font-size="9" text-anchor="middle">${t('WAIT','等待')}</text><path class="jl-route" d="${phase>=2?'M116 148V57H276':phase>=1?'M116 148V57':'M116 148V112'}" stroke="#1953D9" stroke-width="5" stroke-linecap="round" fill="none"/>${car(phase>=2?258:116,phase>=2?57:phase>=1?57:132,'#1953D9',phase>=2?90:0)}<rect x="228" y="118" width="72" height="30" rx="7" fill="white"/><circle cx="245" cy="133" r="7" fill="${phase>=2?'#087452':'#C8443A'}"/><text x="259" y="137" font-size="9">${phase>=2?t('GREEN','绿灯'):t('WAIT','等待')}</text>`;
  }else if(kind==='replacement'){
   art=`<rect width="320" height="168" fill="#F3F5F9"/><path d="M33 58H287" stroke="#98A3B7" stroke-width="5" stroke-dasharray="5 4"/><rect x="122" y="43" width="76" height="30" rx="8" fill="#FFF0D9"/><path d="m148 51 16 14m0-14-16 14" stroke="#A85C15" stroke-width="3"/><path class="jl-route" d="M33 58V128H287V58" stroke="#C57618" stroke-width="5" fill="none" stroke-linejoin="round"/>${[33,287].map(x=>`<circle cx="${x}" cy="58" r="8" fill="white" stroke="#1953D9" stroke-width="3"/>`).join('')}<circle cx="${phase?210:65}" cy="128" r="10" fill="#C57618"/><rect x="${phase?203:58}" y="123" width="14" height="9" rx="2" fill="white"/><text x="33" y="29" text-anchor="middle">${t('Start','起点')}</text><text x="287" y="29" text-anchor="middle">${t('Arrive','终点')}</text><text x="160" y="101" text-anchor="middle">${t('Replacement bus','接驳巴士')}</text><text x="160" y="154" text-anchor="middle" font-size="10">${t('Confirm the designated stop','确认指定上车地点')}</text>`;
  }else if(kind==='crash'){
   art=`<rect width="320" height="168" fill="#EDF1F6"/><rect x="0" y="61" width="320" height="79" fill="#D5DDE8"/><path d="M0 101h320" stroke="white" stroke-width="3" stroke-dasharray="12 9"/>${car(118,84,'#1953D9',90)}${car(165,83,'#69758A',75)}<path d="m222 63 22 39h-44Z" fill="#FFF0D9" stroke="#A85C15" stroke-width="2"/><text x="222" y="94" text-anchor="middle" font-size="24">!</text><rect x="17" y="15" width="139" height="29" rx="6" fill="white"/><text x="86" y="34" text-anchor="middle">${t('Stop • Safety • Help','停车 · 安全 · 协助')}</text><text x="160" y="159" text-anchor="middle" font-size="10">${t('Do not stand in moving traffic','不要站在行进车流中')}</text>`;
  }else if(kind==='payment'){
   art=`<rect width="320" height="168" fill="#F0F4FA"/><rect x="29" y="62" width="85" height="53" rx="9" fill="#1953D9"/><text x="42" y="84" fill="white" font-size="11">Visa / MC</text><path class="jl-route" d="M129 89h61m-10-8 10 8-10 8" fill="none" stroke="#1953D9" stroke-width="4"/><rect x="211" y="33" width="75" height="107" rx="12" fill="#27364C"/><rect x="221" y="44" width="55" height="45" rx="6" fill="#DDF4E9"/><path d="m235 65 9 9 17-20" stroke="#087452" fill="none" stroke-width="4"/><circle cx="249" cy="111" r="10" fill="#86B990"/><text x="160" y="159" text-anchor="middle" font-size="10">${t('Check the reader confirms your tap','确认读卡器提示刷卡成功')}</text>`;
  }else if(kind==='boarding'){
   art=`<rect width="320" height="168" fill="#F0F3F8"/><rect x="22" y="18" width="276" height="85" rx="12" fill="#C9D8EF"/><rect x="124" y="32" width="72" height="71" rx="4" fill="white"/>${[68,252].map(x=>`<circle cx="${x}" cy="124" r="9" fill="#1953D9"/><path d="M${x} 138v20" stroke="#1953D9" stroke-width="13" stroke-linecap="round"/>`).join('')}<path class="jl-route" d="M160 53v84m-9-10 9 10 9-10" stroke="#087452" stroke-width="5" fill="none"/><text x="160" y="159" text-anchor="middle" font-size="10">${t('Let passengers leave first','让乘客先下车')}</text>`;
  }else{
   art=`<rect width="160" height="168" fill="#DDF4E9"/><rect x="160" width="160" height="168" fill="#E9EEFC"/><path d="M160 0v168" stroke="#8897AE" stroke-dasharray="5 5"/><text x="80" y="29" text-anchor="middle">${t('Free Tram Zone','电车免费区')}</text><text x="240" y="29" text-anchor="middle">${t('Outside the zone','免费区以外')}</text><path class="jl-route" d="M30 111H287" stroke="#1953D9" stroke-width="5" fill="none"/><circle cx="40" cy="111" r="7" fill="white" stroke="#1953D9" stroke-width="3"/><circle cx="280" cy="111" r="7" fill="white" stroke="#1953D9" stroke-width="3"/><rect x="${phase?202:55}" y="67" width="53" height="29" rx="6" fill="#1953D9"/><rect x="${phase?211:64}" y="73" width="34" height="10" rx="2" fill="white"/>`;
  }
  return `<figure class="jl-visual"><svg viewBox="0 0 320 168" role="img" aria-label="${esc(caption)}" xmlns="http://www.w3.org/2000/svg"><g font-family="system-ui,sans-serif" font-size="12" fill="#192132">${art}</g></svg></figure>`;
 }
 const choices=(items,field,value)=>`<div class="jl-choices" role="group">${items.map(([id,en,zh])=>`<button class="jl-choice ${value===id?'is-selected':''}" data-jl="profile" data-field="${field}" data-value="${id}" aria-pressed="${value===id}"><span>${value===id?svg('check'):''}</span><span>${esc(t(en,zh))}</span></button>`).join('')}</div>`;
 function background(){return `<span class="jl-kicker">${t('START WITH YOU','从你的背景开始')}</span><h1>${t('Where are you coming from?','你来自哪个国家或地区？')}</h1><div class="jl-country-grid" role="group" aria-label="${t('Country or region','国家或地区')}">${jlCountries.map(([id,en,zh])=>`<button class="jl-country ${state.profile.country===id?'is-selected':''}" data-jl="country" data-value="${id}" aria-pressed="${state.profile.country===id}">${flag(id)}<span>${esc(t(en,zh))}</span></button>`).join('')}</div>`}

 const licencePlan=()=>jlLicencePlan(active(),state.profile.country);
 const licenceSelect=(field,label,options,value)=>`<label class="lic-field"><span>${label}</span><select data-licence-field="${field}">${options.map(([id,en,zh])=>`<option value="${id}" ${String(value??'')===id?'selected':''}>${esc(t(en,zh))}</option>`).join('')}</select></label>`;
 const licencePlate=(grade,small=false)=>`<span class="lic-plate lic-${grade.toLowerCase()} ${small?'is-small':''}" aria-hidden="true">${jlLicenceGrades[grade]?.letter||'?'}</span>`;
 function licence(){const p=active(),m=licencePlan();return `<span class="jl-kicker">${t('VICTORIA · CAR LICENCE','维州 · 汽车驾照')}</span><h1>${t('Find your licence pathway.','找到适合你的驾照路径。')}</h1><div class="lic-status">${choices([['valid','Current overseas car licence','现行有效的海外汽车驾照'],['none','No driver licence yet','尚未取得驾驶执照'],['learner','I have a learner permit','已有学习驾照'],['expired','Expired, suspended or cancelled licence','驾照已过期、停牌或被吊销']],'licence',p.licence)}</div>${p.licence?`${licenceSelect('age',t('Your age group','目前年龄'),[['','Choose your age','选择年龄'],['15','Under 16','未满 16 岁'],['17','16–17','16–17 岁'],...Array.from({length:7},(_,i)=>[String(i+18),String(i+18),`${i+18} 岁`]),['25','25 or older','25 岁或以上']],p.age)}${p.licence==='valid'?`${licenceSelect('issuer',t('Licence issued in','驾照发证国家或地区'),jlCountries,p.issuer||state.profile.country||'OTHER')}${Number(p.age)>=18?licenceSelect('experience',t('Licence held since age 18','满 18 岁后的持证年限'),[['','Choose the duration','选择持证时长'],['lt1','Under 1 year','不足 1 年'],['1to3','1 to under 3 years','1 年至不足 3 年'],['3to4','3 to under 4 years','3 年至不足 4 年'],['4plus','4 years or more','4 年或以上']],p.experience):''}<p class="lic-field-note">${t('Count valid car-licence time, excluding learner-permit time and invalid periods.','只计算有效汽车驾照的持证时间，不包括学习驾照及失效期间。')}</p>${m.error?`<p class="lic-error" role="alert">${t('The duration cannot exceed your years since turning 18.','持证时长不能超过满 18 岁后经过的时间。')}</p>`:''}${Number(p.age)===24&&p.experience==='3to4'?licenceSelect('earlyIssue',t('First issued before age 21?','首次取得驾照时是否未满 21 岁？'),[['','Not sure','不确定'],['before21','Before 21','未满 21 岁'],['after21','At 21 or later','21 岁或以上']],p.earlyIssue):''}<label class="lic-checkbox"><input type="checkbox" data-licence-field="interrupted" ${p.interrupted?'checked':''}><span>${t('My licence history includes expiry, suspension or cancellation.','我的持证记录中曾出现过期、停牌或吊销。')}</span></label>${licenceSelect('stay',t('Living in Victoria','在维州的居住安排'),[['unsure','Not sure yet','尚未确定'],['short','Under 6 months','少于 6 个月'],['long','6 months or longer','6 个月或以上']],p.stay||'unsure')}`:p.licence==='learner'?licenceSelect('learnerPlace',t('Which learner permit?','持有哪种学习驾照？'),[['','Choose your permit','选择学习驾照类型'],['vic','Victorian L permit','维州 L 学习驾照'],['overseas','Overseas learner permit','海外学习驾照']],p.learnerPlace):''}`:''}${m.ready?licenceResult():''}${source('convert','issueguide','learner','probationary')}`}
 function licenceResult(){const p=active(),m=licencePlan();if(!m.ready)return '';const grade=jlLicenceGrades[m.stage],title=grade?pair(grade.label):m.stage==='WAIT'?t('L permit: from age 16','L 学习驾照：最早 16 岁'):m.reason==='earlyIssue'?t('Confirm P2 or Full','需确认 P2 或 Full'):t('Licence-history review','先核验持证记录');const reasons={young:['You can prepare now; a Victorian car learner permit starts at 16.','现在可以提前了解，维州汽车学习驾照最早 16 岁申请。'],new:['Begin with L. The P stage you enter later depends on your age when licensed.','从 L 开始，之后进入哪个 P 牌阶段，取决于取得驾照时的年龄。'],learner:['Continue from your Victorian L, meeting the age-based learner requirements.','从现有维州 L 继续，完成对应年龄的学习期要求。'],overseasLearner:['An overseas learner permit is not a full licence. Ask VicRoads about recognition and credit before following a learner plan.','海外学习驾照不是完整驾照。先向 VicRoads 确认认可及经历抵扣，再按确认的学习路径推进。'],invalid:['Have VicRoads check your licence history. Do not drive while your authority to drive is invalid.','先让 VicRoads 核验持证记录；驾驶资格失效期间不要上路。'],interrupted:['Expired, suspended or cancelled periods may affect recognised experience and the licence issued.','过期、停牌或吊销记录可能影响获认可的持证时间和最终牌照。'],earlyIssue:['A licence first obtained before 21 and held for under four years needs a closer check. VicRoads must confirm P2 or Full and any remaining P period.','21 岁前取得驾照、持证不足四年时，需要进一步核验。由 VicRoads 确认 P2 或 Full 及剩余 P 牌期限。'],under18:['A Victorian car driver licence cannot be issued before 18; the learner pathway may apply from 16.','维州汽车驾驶执照最早 18 岁签发，16 岁起可按条件进入学习驾照路径。'],conversion:['Your age and recognised licence time indicate this entry stage, after the required checks and assessments.','年龄和获认可的持证时长指向这一入门阶段，仍须完成适用的核验与评估。']};const route=m.stage==='L'||m.stage==='WAIT'?['L',...(m.age>=21?[]:['P1']),'P2','FULL']:m.stage==='P1'?['P1','P2','FULL']:m.stage==='P2'?['P2','FULL']:m.stage==='FULL'?['FULL']:[];return `<section class="lic-result" data-grade="${m.stage}"><span class="jl-kicker">${t('YOUR LIKELY ENTRY','你的参考入门阶段')}</span><div class="lic-result-heading">${grade?licencePlate(m.stage):'<span class="lic-review-mark" aria-hidden="true">?</span>'}<h2>${title}</h2></div><p>${pair(reasons[m.reason]||reasons.conversion)}</p>${route.length>1?`<div class="lic-route-strip" aria-label="${esc(t('Your licence route','你的驾照路径'))}">${route.map((g,i)=>`${i?'<span aria-hidden="true">→</span>':''}<span>${licencePlate(g,true)}<small>${g==='FULL'?'Full':g}</small></span>`).join('')}</div>`:''}${p.licence==='valid'?`<p class="lic-deadline">${p.stay==='short'?t('A valid current overseas licence may be used for a stay under six months, subject to its conditions. Carry the required translation or English IDP.','居住少于六个月时，符合条件的有效海外驾照可能可以使用；携带所需翻译或英文国际驾驶许可。'):t('If living in Victoria for six months or longer, convert within six months of starting to live here.','在维州居住六个月或更久时，须在开始居住后的六个月内完成转换。')}</p>`:''}<small>${t('VicRoads confirms your evidence, credited experience and final licence.','最终牌照及持证经历抵扣，以 VicRoads 核验为准。')}</small><a class="lic-official-link" href="${jlSources.convert[1]}" target="_blank" rel="noopener noreferrer">${t('Confirm with VicRoads','到 VicRoads 确认路径')} ↗</a></section>`}
 function licenceTypes(){const p=active(),m=licencePlan(),selected=Object.hasOwn(jlLicenceGrades,p.licenceStage)?p.licenceStage:(jlLicenceGrades[m.stage]?m.stage:'L'),g=jlLicenceGrades[selected];return `<span class="jl-kicker">${t('L → P1 → P2 → FULL','看懂 L、红 P、绿 P 与 Full')}</span><h1>${t('Know what each licence means.','弄懂每一种牌照。')}</h1>${m.ready?`<p class="lic-field-note">${t('Your reference entry:','你的参考入门阶段：')} ${jlLicenceGrades[m.stage]?pair(jlLicenceGrades[m.stage].label):t('VicRoads review','需由 VicRoads 核验')}</p>`:''}<nav class="lic-grade-tabs" aria-label="${t('Licence stages','驾照阶段')}">${Object.entries(jlLicenceGrades).map(([id,v])=>`<button data-jl="licence-grade" data-value="${id}" aria-pressed="${selected===id}">${licencePlate(id,true)}<span>${pair(v.label)}</span></button>`).join('')}</nav><section class="lic-grade-card"><div class="lic-result-heading">${licencePlate(selected)}<h2>${pair(g.title)}</h2></div><p>${pair(g.summary)}</p><ul>${g.facts.map(f=>`<li>${pair(f)}</li>`).join('')}</ul></section>${selected==='L'&&m.ready&&['new','learner'].includes(m.path)?callout(t('Your learner baseline','你的学习期基本要求'),t(`Minimum permit period: ${m.months} months. ${m.hours?'Under 21: log 120 hours, including 20 at night.':'The under-21 120-hour logbook rule does not apply; supervised experience is still needed.'} Ps cannot be issued before 18.`,`最短连续学习持证期：${m.months} 个月。${m.hours?'未满 21 岁须记录 120 小时，其中 20 小时为夜间。':'未满 21 岁的 120 小时记录要求不适用，但仍需积累监督驾驶经验。'}取得 P 牌最早须满 18 岁。`)):''}${source('stages','plateRules','probationary','full')}`}
 function licenceApplicationSteps(m){if(m.stage==='WAIT')return [[t('Prepare before turning 16','16 岁前先做好准备'),t('Read the road rules and prepare identity documents. Apply for a car learner permit only when eligible.','先了解道路规则和准备身份证明，符合年龄与其他资格后再申请汽车学习驾照。'),'learner']];if(['review','reviewLearner'].includes(m.path))return [[t('Have your record checked','先核验你的记录'),t('Use the official checker and ask VicRoads about the complete licence or permit history, including invalid periods and overseas learner credit.','通过官方工具及 VicRoads 确认完整持证记录，包括失效期间、海外学习驾照经历抵扣等。'),'convert'],[t('Confirm the applicable pathway','确认适用的申请路径'),t('Confirm which licence you can receive and whether tests or a Victorian learner permit are required. Do not assume an exemption.','确认可取得哪种牌照、是否需要考试或维州学习驾照，不默认可以豁免。'),'convert'],[t('Prepare and follow the assessed steps','按核验结果准备并推进'),t('Bring identity, address and licence evidence, and any required English translation. Book the appointments and tests VicRoads specifies.','准备身份、地址、驾照证明及所需英文翻译，按 VicRoads 指定安排预约或考试。'),'id']];if(['new','learner'].includes(m.path)){const steps=[];if(m.path==='new')steps.push([t('Learn the rules and get L','学习规则，取得 L'),t('Start through myVicRoads, complete the Learner Permit Test, then follow the identity, eyesight and photo instructions to obtain your permit.','通过 myVicRoads 开始，完成学习驾照知识考试，再按指引提交身份资料、检查视力和拍照，取得学习驾照。'),'learner']);steps.push([t('Build supervised experience','积累监督驾驶经验'),t(`Hold your learner permit continuously for at least ${m.months} months. ${m.hours?'Log at least 120 hours, including 20 at night.':'Practise with an eligible supervisor; the under-21 logbook minimum does not apply.'}`,`连续持有学习驾照至少 ${m.months} 个月。${m.hours?'记录至少 120 小时，其中 20 小时为夜间。':'与符合条件的监督者练习，未满 21 岁的最低记录时数要求不适用。'}`),'probationary'],[t('Hazard perception, then Drive Test','危险感知，再参加路考'),t('Meet the eligibility requirements, including minimum age 18, complete the Hazard Perception Test and book your Drive Test.','满足包括最低 18 岁在内的资格要求，完成危险感知考试，再预约路考。'),'probationary'],[t('Receive your P licence','取得相应 P 牌'),t('New drivers licensed under 21 normally enter P1; those licensed at 21 or older enter P2. Carry the temporary licence until your card is available.','首次取得驾照时未满 21 岁通常进入 P1，已满 21 岁则进入 P2。在正式卡片可用前携带临时驾照。'),'probationary']);return steps;}const steps=[];if(m.path==='conversion')steps.push([t('Complete the knowledge course and test','先完成道路规则知识课程与考试'),t('The non-recognised-licence pathway includes the Learner Permit Test, even when you already have an overseas car licence.','非认可国家／地区的驾照转换路径包含学习驾照知识考试，即使你已经持有海外汽车驾照。'),'conversionSteps']);else steps.push([t('Confirm the recognised-licence route','确认认可驾照转换路径'),t('This country has a recognised-licence route. It normally uses licence and identity verification rather than the standard three-test route; confirm your case with VicRoads.','该发证国家有认可驾照转换路径，通常以驾照及身份核验为主。由 VicRoads 确认你是否适用，不能仅凭年限判断免考。'),'convert']);steps.push([t('Prepare original evidence','准备原始证明资料'),t('Bring your overseas licence, identity and Victorian address evidence. Arrange an English translation or English IDP if required.','准备海外驾照、身份证明与维州地址证明，按要求安排英文翻译或英文国际驾驶许可。'),'id'],[t('Book and attend verification','预约并完成核验'),t('Have VicRoads verify your licence and identity. Bring required eyesight correction and medical information.','由 VicRoads 核验驾照及身份，按要求携带眼镜、隐形眼镜或医疗资料。'),'convert']);if(m.path==='conversion')steps.push([t('Hazard Perception Test, then Drive Test','完成危险感知考试与路考'),t('Follow the conversion instructions to complete the required Hazard Perception Test and practical Drive Test.','按转换路径指引完成所需危险感知考试和实际路考。'),'conversionSteps']);steps.push([t('Get the assessed Victorian licence','取得核验后确定的维州驾照'),t('VicRoads confirms your licence class and any P period using verified history. Follow the photo, signature and temporary-licence instructions.','VicRoads 根据核验后的记录确定牌照级别及 P 牌期限，按要求拍照、签名并领取临时驾照。'),'convert']);return steps;}
 function licenceApplication(){const p=active(),m=licencePlan();if(!m.ready)return `<h1>${t('Your application, step by step.','按步骤申请你的驾照。')}</h1><p>${t('Add your licence details to see the appropriate application steps.','填写持证情况后，即可查看适用的申请步骤。')}</p>${button(t('Set my licence details','填写驾照情况'),'step','data-index="1"')}${source('convert','learner')}`;const items=licenceApplicationSteps(m);return `<span class="jl-kicker">${t('YOUR APPLICATION PLAN','你的申请步骤')}</span><h1>${t('From preparation to your licence.','从准备资料，到取得驾照。')}</h1><p>${m.path==='conversion'?t('Knowledge → evidence → verification → practical assessments.','知识课程 → 资料准备 → 身份与驾照核验 → 实际驾驶评估。'):m.path==='recognised'?t('Confirm recognition → prepare evidence → attend VicRoads.','确认认可路径 → 准备证明 → 到 VicRoads 核验。'):t('Open each step to see what to prepare.','展开每一步，查看该准备什么。')}</p><div class="lic-application">${items.map(([title,copy,src],i)=>`<details name="licence-application" data-licence-step="${i}" ${i===(p.applicationStep??0)?'open':''}><summary><span class="lic-application-number">${i+1}</span><strong>${title}</strong><span class="lic-chevron" aria-hidden="true">+</span></summary><div class="lic-application-body"><p>${copy}</p><a href="${jlSources[src][1]}" target="_blank" rel="noopener noreferrer">${t('Open official instructions','查看官方办理指引')} ↗</a></div></details>`).join('')}</div>${source('convert','conversionSteps','learner','probationary')}`}

 function road(){const p=active(),q=jlRoadTopics[p.topic];return `<span class="jl-kicker">${t('YOUR BACKGROUND × VICTORIA','你的背景 × 维州规则')}</span><h1>${t('Same attention. New habits.','同样专注，换一种道路习惯。')}</h1><div class="jl-tabs" role="group" aria-label="${t('Road topics','道路主题')}">${jlRoadTopics.map((v,i)=>`<button data-jl="road-topic" data-index="${i}" aria-pressed="${p.topic===i}">${pair(v.title)}</button>`).join('')}</div>${p.topic===0?`<div class="jl-compare"><div><small class="jl-country-label">${flag(state.profile.country)}<span>${esc(country())}</span></small><strong>${state.profile.side==='right'?t('Drive on the right','靠右行驶'):state.profile.side==='left'?t('Drive on the left','靠左行驶'):t('Local road rules','当地道路规则')}</strong></div><div><small class="jl-country-label">${flag('AU')}<span>Victoria</span></small><strong>${t('Drive on the left','靠左行驶')}</strong></div></div>`:''}${visual(q.scene)}<h2>${pair(q.title)}</h2><p>${pair(q.body)}</p>${callout(t('On the road','实际行驶时'),pair(q.feedback))}${source(q.source)}`}

 function ticket(){const p=active(),mode=p.mode,habit=state.profile.country==='CN'?t('QR codes & transit cards','乘车码与交通卡'):t('Local tickets & travel cards','当地车票与交通卡');
  const localHabit=state.profile.habit==='cash'?[t('Prepare before boarding','上车前准备好'),t('You cannot buy or top up myki on a tram or bus.','无法在电车或公交车上购买或充值 myki。')]:state.profile.habit==='digital'?[t('Your phone works here too','这里也能刷手机'),t('Use Visa or Mastercard directly, or through Apple Pay or Google Pay. Keep using the same card or device.','可直接刷 Visa、Mastercard，或使用 Apple Pay、Google Pay；全程使用同一张卡或同一台设备。')]:[t('Check the mode and zone','确认方式与票区'),t('A familiar card action can have different tap-off rules here.','熟悉的刷卡动作，在这里可能有不同的下车刷卡规则。')];
  const info=mode==='train'?[t('Train · tap on & off','火车 · 上下车都刷卡'),t('Tap on at the start and off at the end. Check the reader confirmation.','出发时刷卡，结束时再刷卡，并确认读卡器提示。')]:mode==='bus'?[t('Bus · tap on & off','公交 · 上下车都刷卡'),t('On Melbourne myki-enabled buses, use myki, a supported bank card or digital wallet. Tap on and off with the same card or device.','墨尔本支持 myki 的公交也可刷受支持的银行卡或手机钱包，上下车使用同一张卡或同一台设备。')]:[t('Tram · the zone matters','电车 · 要看票区'),t('Entirely inside the Free Tram Zone: no tap on or off. Zone 1: tap on; no tap off needed. Entirely in Zone 2: tap on and off.','全程在电车免费区内无需刷卡。Zone 1 上车刷，下车无需刷；全程在 Zone 2 内上下车都刷。')];
  return `<span class="jl-kicker">${t('YOUR BACKGROUND × LOCAL SYSTEM','你的背景 × 本地票制')}</span><h1>${t('One trip. Know the rhythm.','一趟行程，先弄懂刷卡节奏。')}</h1><div class="jl-compare"><div><small class="jl-country-label">${flag(state.profile.country)}<span>${esc(country())} · ${t('transport','公共交通')}</span></small><strong>${habit||t('A fresh start','从头认识')}</strong></div><div><small class="jl-country-label">${flag('AU')}<span>Melbourne</span></small><strong>${localHabit[0]}</strong><p>${localHabit[1]}</p></div></div><h2>${t('Three ways to pay','三种支付方式')}</h2><ul class="jl-payment-options"><li>${svg('card')}<div><strong>Visa / Mastercard</strong><small>${t('Tap your contactless debit or credit card.','直接轻触非接触式借记卡或信用卡。')}</small></div></li><li>${svg('phone')}<div><strong>Apple Pay / Google Pay</strong><small>${t('Use a supported Visa or Mastercard in your phone or watch wallet.','使用手机或手表钱包中受支持的 Visa 或 Mastercard。')}</small></div></li><li>${svg('train')}<div><strong>myki</strong><small>${t('Physical myki or Mobile myki on Android.','实体 myki，或 Android 上的 Mobile myki。')}</small></div></li></ul><p class="jl-note">${t('Available on Melbourne trains, trams and myki-enabled buses. Check regional services separately.','适用于墨尔本火车、电车及支持 myki 的公交；区域交通请另行确认。')}</p>${callout(t('One card or device, throughout','全程使用同一张卡或同一台设备'),t('A phone, watch and physical card count separately, even with the same bank account.','即使绑定同一银行账户，手机、手表和实体卡也会被分别计费。'))}<div class="jl-tabs" role="group" aria-label="${t('Travel modes','交通方式')}">${[['train','Train','火车'],['tram','Tram','电车'],['bus','Bus','公交']].map(([id,en,zh])=>`<button data-jl="ticket-mode" data-value="${id}" aria-pressed="${mode===id}">${t(en,zh)}${p.ticketSeen.includes(id)?'<small>✓</small>':''}</button>`).join('')}</div>${visual(mode==='tram'?'ticket':'payment')}<h2>${info[0]}</h2><p>${info[1]}</p>${callout(t('A card is not proof of eligibility','有卡不等于有优惠资格'),t('Check your student concession eligibility. To use an eligible concession with contactless, link it to the exact card or device in the Transport Victoria portal and carry your proof.','先确认学生优惠资格。使用非接触支付享优惠时，须在 Transport Victoria 门户绑定实际使用的卡片或设备，并携带资格证明。'))}${source('myki','payments','contactless','concessions','students')}`;
 }
 const caseIds=()=>state.track==='driving'?['insurance','breakdown','minor','injury','property','rental','hook']:custom()?custom().caseIds(active()):active().step===3?['works','sudden','accessible','night']:['missed','boarding','inspection','declined','phone','unsafe'];
 const caseList=ids=>{const p=active();return `<div class="jg-case-list">${ids.map(id=>`<button class="jl-case jg-case ${p.cases[id]?'is-viewed':''}" data-jl="case" data-id="${id}"><span class="jg-case-art">${jlGuideArt(jlGuides[id].scene)}</span><div><strong>${pair(jlGuides[id].title)}</strong><small>${p.cases[id]?t('Viewed · open again','已浏览 · 再看看'):t('Open guide','查看处理方法')}</small></div>${svg('arrow')}</button>`).join('')}</div>`};
 function caseHub(ids,title,copy){return `<span class="jl-kicker">${t('EVERYDAY SITUATIONS','日常情景处理')}</span><h1>${title}</h1><p>${copy}</p>${caseList(ids)}`}
 const campusContext={t,pair,esc,source,caseList,active,save};Object.values(jlCustomTracks).forEach(c=>c.bind(campusContext));
 const trackTitle=()=>custom()?pair(custom().title):({driving:t('Driving journey','驾驶学习旅程'),transport:t('Transport journey','交通学习旅程')})[state.track];

 function hookLesson(){return caseHub(['hook'],t('A right turn, from the left.','从左侧完成右转。'),t('Follow the car through a signed hook-turn intersection.','沿着图解，看看有标志路口的钩形转弯过程。'))}

 function lesson(){const p=active();if(p.step===5)return recap();if(custom())return custom().lesson(p,campusContext);if(p.step===0)return background();if(state.track==='driving'){if(p.step===1)return licence();if(p.step===2)return licenceTypes();if(p.step===3)return licenceApplication();return caseHub(caseIds(),t('Help when you are on the road.','上路后，遇到问题这样处理。'),t('Insurance, breakdowns, accidents and local road situations.','保险、抛锚、事故与本地道路情景。'))+`<details class="lic-road-basics"><summary>${t('Compare Victorian road rules','对照维州道路规则')}</summary>${road().replaceAll('<h1>','<h2>').replaceAll('</h1>','</h2>')}</details>`}if(p.step===1)return ticket();if(p.step===2)return hookCaseIntro('tram');if(p.step===3)return caseHub(caseIds(),t('Your journey changes. You have options.','行程改变了，你还有选择。'),t('Find a way through disruptions, replacement travel and late-night changes.','遇到停运、接驳或深夜变化时，找到可行的下一步。'));return caseHub(caseIds(),t('A little help, while travelling.','乘车途中，多一点应对方法。'),t('Payment problems, missed stops and finding support.','支付失败、坐过站或需要帮助时，可以这样处理。'))}

 function hookCaseIntro(id){return caseHub([id],t('Leaving the free zone?','要离开电车免费区？'),t('Follow a tram journey and see how payment changes.','跟着一趟电车行程，看看何时需要付费。'))}


 function scenario(){const session=active().session,data=jlGuides[session.id],index=session.index,step=data.steps[index],variant=data.variants?.find(v=>v.id===session.variant)||data.variants?.[0],body=variant?.body?.[index]||step.body,urgent=data.urgent||(session.id==='breakdown'&&variant?.id==='fire'?variant.note:null);return `<span class="jl-kicker">${state.track==='driving'?t('DRIVING GUIDE','驾驶情景指南'):custom()?pair(custom().guideKicker):t('TRAVEL GUIDE','出行情景指南')}</span><h1>${pair(data.title)}</h1><p class="jg-intro">${pair(data.intro)}</p>${urgent?`<aside class="jg-urgent">${svg('phone')}<span>${pair(urgent)}</span></aside>`:''}${data.variants?`<div class="jl-tabs jg-variants" role="group" aria-label="${t('Your situation','现场情况')}">${data.variants.map(v=>`<button data-jl="guide-variant" data-value="${v.id}" aria-pressed="${variant.id===v.id}">${pair(v.label)}</button>`).join('')}</div>`:''}<div class="jg-scene" role="img" aria-label="${esc(pair(data.title)+': '+pair(step.title))}">${jlGuideArt(data.scene,index,variant?.id)}</div><nav class="jg-step-nav" aria-label="${t('Explore the handling steps','查看处理步骤')}">${data.steps.map((v,i)=>`<button data-jl="guide-stage" data-index="${i}" aria-pressed="${i===index}"><span>${i+1}</span><span>${pair(v.title)}</span></button>`).join('')}</nav><section class="jg-stage-panel" aria-live="polite" aria-atomic="true"><h2>${pair(step.title)}</h2><p>${pair(body)}</p>${variant?.note&&!variant.body?.[index]?`<aside class="jg-context">${pair(variant.note)}</aside>`:''}${step.phrase?`<details class="jg-phrase"><summary>${svg('help')}${t('Useful words','需要时可以这样说')}<span aria-hidden="true">+</span></summary><blockquote lang="en">${esc(step.phrase[0])}</blockquote>${window.appLanguage==='zh'?`<p lang="zh-Hans">${esc(step.phrase[1])}</p>`:''}</details>`:''}</section>${source(...data.sources)}`}

 function checklist(){if(custom())return custom().checklist(t);if(state.track==='driving')return [t('Confirm my overseas-conversion or first-licence route with VicRoads.','向 VicRoads 确认海外转换或首次申请路径。'),t('Prepare identity, Victorian address and required licence translations.','准备身份、维州地址证明及所需驾照翻译。'),t('Confirm my entry stage: L, P1, P2 or Full, and any remaining period.','确认入门牌照：L、P1、P2 或 Full，以及适用的剩余期限。'),t('Follow my appointment, learner-period and assessment requirements.','完成适用的预约、学习持证期及评估要求。'),t('Learn Victorian road rules and the conditions of my licence.','熟悉维州道路规则与本人牌照的限制条件。'),t('Keep accident, insurer and roadside-assistance details available.','保存事故处理、保险公司及道路救援资料。'),t('Check insurance cover, excesses and any rental terms before driving.','开车前确认车险保障、自付额及适用的租车条款。')];return [t('Check my ticket method, balance and any concession eligibility.','确认支付方式、余额及优惠资格。'),t('Check the destination, zone and boarding location before leaving.','出发前确认目的地、票区与上车位置。'),t('Check disruptions and allow extra time when services change.','确认运营中断信息，遇到变化时多留时间。'),t('Save official service and accessibility information for a plan B.','保存官方运营与无障碍信息，作为备用方案。')]}
 function recap(){const p=active(),isDone=p.done.includes(5);return `${isDone?`<div class="jl-finished">${svg('check')}</div>`:''}<span class="jl-kicker">${t('PERSONAL TAKEAWAYS','你的个人行动')}</span><h1>${isDone?t('Keep learning, at your pace.','按自己的节奏，继续熟悉这里。'):t('Make the next step yours.','把下一步，变成你的行动。')}</h1><p>${custom()?pair(custom().recapLine):`${esc(country())} → Victoria`} · ${t('Tick actions when you have done them outside this exercise.','在实际完成后，再勾选这些行动。')}</p><div class="jl-check-progress" aria-live="polite"><span class="jl-check-meter"><span style="--value:${p.checks.length/checklist().length}"></span></span><small>${t(`${p.checks.length} of ${checklist().length} done`,`已完成 ${p.checks.length}/${checklist().length}`)}</small></div><div class="jl-checklist">${checklist().map((text,i)=>`<label><input type="checkbox" data-jl="checklist" data-index="${i}" ${p.checks.includes(i)?'checked':''}><span>${text}</span></label>`).join('')}</div>${state.track==='driving'?licenceResult():''}${source(...(state.track==='driving'?['convert','learner','crash','cover','tac','hire','breakdown','hook']:custom()?custom().sources:['works','access','payments','contactless','concessions','myki','students']))}${isDone?`<div class="jl-inline-actions">${button(t(`Next: ${nextTrackName()}`,`下一条：${nextTrackName()}`),'other','','jl-btn jl-secondary')}</div>`:''}`}
 const nextTrack=()=>tracks[(tracks.indexOf(state.track)+1)%tracks.length];
 const nextTrackName=()=>pair(jlTracks[nextTrack()].name);
 function ready(){const p=active();if(p.session)return true;if(custom()&&p.step===0)return custom().ready(p);if(p.step===0)return !!state.profile.country;if(state.track==='driving'&&p.step===1)return licencePlan().ready;return true}

 function footer(){const p=active();let label=t('Continue','继续'),help='';if(p.session){label=p.session.index===jlGuides[p.session.id].steps.length-1?t('Back to situations','返回情景列表'):t('See the next step','看看下一步')}else if(p.step===0&&!ready()){help=custom()?pair(custom().startHelp):t('Choose a country or region.','请选择国家或地区。')}else if(p.step===5){label=p.saved?t('Checklist saved · back to Journey Tree','清单已保存 · 返回旅程树'):t('Save checklist & finish','保存清单并完成')}else if(state.track==='driving'&&p.step===1&&!ready()){help=t('Add your licence status, age and any required history.','请填写持证情况、年龄及适用的持证经历。')}else if(p.step===4){label=t('My takeaway checklist','我的行动清单')}return `${help?`<small>${help}</small>`:''}${button(label+svg(p.step===5?'save':'arrow'),'next',ready()?'':'disabled')}`}

 const overview=document.querySelector('#overview');
 const list=document.createElement('section');list.className='jl-overview';list.id='learning-overview';list.hidden=true;overview.querySelector('.journey-top').after(list);
 let modalClosing=false,modalOrigin=null,modalReturn=null;
 const panel=document.createElement('section');panel.className='jl-panel';panel.hidden=true;panel.id='learning-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','jl-panel-title');document.body.append(panel);
 const nav=document.querySelector('.category-nav');nav.setAttribute('role','tablist');
 function renderTabs(){nav.innerHTML=[['healthcare','Healthcare','医疗'],['transport','Transport','交通'],['driving','Driving','驾驶'],...Object.entries(jlCustomTracks).map(([id,c])=>[id,...c.tab])].map(([id,en,zh])=>`<button role="tab" data-jl="track" data-track="${id}" aria-selected="${state.track===id}" tabindex="${state.track===id?0:-1}" class="${state.track===id?'active':''}">${t(en,zh)}</button>`).join('');const active=nav.querySelector('.active');if(active&&nav.scrollWidth>nav.clientWidth)nav.scrollTo({left:active.offsetLeft-(nav.clientWidth-active.offsetWidth)/2,behavior:reduced.matches?'auto':'smooth'})}
 function renderOverview(){document.body.dataset.journeyTrack=state.track;renderTabs();list.hidden=state.track==='healthcare';if(list.hidden)return;const p=active(),track=jlTracks[state.track],driving=state.track==='driving',phases=driving?[t('Find your route','找到你的路径'),t('Get your licence','取得驾照'),t('Ready for the road','上路前准备')]:custom()?custom().phases(t):[t('Get ready','出发前准备'),t('Explore situations','情景处理'),t('Your next steps','你的下一步')];list.innerHTML=`<div class="journey-top"><div class="journey-banner"><img src="assets/${track.image}" alt="${pair(track.name)}"><div class="banner-copy"><span>${t('EVERYDAY GUIDES','日常生活指南')}</span><h1>${pair(track.name)}</h1></div></div></div><header class="intro"><h2 class="topic-title">${pair(track.intro)}</h2><p>${pair(track.copy)}</p></header><div class="jl-summary"><span>${t(`${p.done.length} / 6 sections explored`,`${p.done.length} / 6 个章节已浏览`)}</span>${button((p.saved?t('Review checklist','查看清单'):p.reached>0||p.done.length?t('Continue journey','继续旅程'):t('Start journey','开始旅程'))+svg('arrow'),'open','','jl-resume')}</div><div class="grid jl-steps">${track.steps.map(([title,copy],i)=>{const group=i<2?0:i<(driving?4:5)?1:2;return `${(driving?[0,2,4]:[0,2,5]).includes(i)?`<h2 class="phase-divider"><span>${phases[group]}</span><span class="phase-count">${group===0?'01–02':group===1?(driving?'03–04':'03–05'):(driving?'05–06':'06')}</span></h2>`:''}<button class="card interactive jl-step-card ${p.done.includes(i)?'is-done':''}" data-jl="step" data-index="${i}" ><img class="editorial-cover" src="assets/${jlStepImages[state.track][i]}" alt="${pair(title)}" loading="lazy"><div class="editorial-body"><div class="editorial-meta"><span>${t('STEP','步骤')} ${String(i+1).padStart(2,'0')}</span><span>${p.done.includes(i)?t('Explored','已浏览'):phases[group]}</span></div><h2>${pair(title)}</h2><p>${pair(copy)}</p><span class="explore">${t('Explore this step','探索这一步')}${svg(p.done.includes(i)?'check':'arrow')}</span></div></button>`}).join('')}</div>`}

 function renderPanel({reset=false,motion=false,direction=1,guideMotion=false}={}){
  panel.hidden=!state.open;if(panel.hidden)return;const p=active(),oldScroll=panel.querySelector('.jl-reading')?.scrollTop||0,focus=document.activeElement,key=focus?.dataset.jl,value=focus?.dataset.value,index=focus?.dataset.index,field=focus?.dataset.field;
  const oldProgress=Number(panel.querySelector('[role="progressbar"]')?.getAttribute('aria-valuenow')||0)/6;
  panel.getAnimations({subtree:true}).forEach(a=>a.cancel());panel.dataset.sceneMotion=String(motion||guideMotion);
  panel.innerHTML=`<div class="jl-detail-stack"><nav class="jl-rail" aria-label="${t('Learning steps','学习步骤')}">${jlTracks[state.track].steps.map(([title],i)=>`<button data-jl="step" data-index="${i}"  ${i===p.step?'aria-current="step"':''} class="${p.done.includes(i)?'is-done':''}" aria-label="${esc(t('Step','步骤')+' '+(i+1)+': '+pair(title))}"><span>${p.done.includes(i)?svg('check'):i+1}</span></button>`).join('')}</nav><section class="jl-dialog"><header class="jl-header">${button(svg('back'),'back',`aria-label="${t('Back','返回')}"`,'')}<div><strong id="jl-panel-title">${trackTitle()}</strong><small>${t('Step','步骤')} ${p.step+1} / 6${p.session?' · '+t('Guide','情景指南'):''}</small></div>${button(window.appLanguage==='zh'?'EN':'中文','language',`aria-label="${t('Switch to Chinese','切换英文')}"`,'')}${button(svg('close'),'close',`aria-label="${t('Back to Journey Tree','返回旅程树')}"`,'')}</header><div class="jl-top-progress" role="progressbar" aria-label="${t('Journey progress','学习进度')}" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${p.done.length}"><span style="--progress:${p.done.length/6}"></span></div><div class="jl-reading">${p.session?scenario():lesson()}</div><footer class="jl-footer">${footer()}</footer></section></div>`;
  const reading=panel.querySelector('.jl-reading');reading.scrollTop=reset?0:oldScroll;
  if(reset){const heading=reading.querySelector('h1');heading.tabIndex=-1;heading.focus({preventScroll:true})}else if(key){[...panel.querySelectorAll('[data-jl]')].find(el=>el.dataset.jl===key&&el.dataset.value===value&&el.dataset.index===index&&el.dataset.field===field&&!el.disabled)?.focus({preventScroll:true})}
  if(motion&&!reduced.matches)panel.querySelector('.jl-dialog').animate([{opacity:.35,transform:`translateY(${direction*48}px)`},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'cubic-bezier(.2,0,0,1)'});
  if(oldProgress!==p.done.length/6&&!reduced.matches)panel.querySelector('.jl-top-progress span').animate([{transform:`scaleX(${oldProgress})`},{transform:`scaleX(${p.done.length/6})`}],{duration:350,easing:'cubic-bezier(.22,1,.36,1)'});
  if(guideMotion&&!reduced.matches){reading.querySelector('.jg-stage-panel')?.animate([{opacity:.3,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'cubic-bezier(.22,1,.36,1)'});reading.querySelector('.jg-art')?.animate([{opacity:.6},{opacity:1}],{duration:240,easing:'ease-out'})}

 }
 function render(options){save();renderOverview();renderPanel(options)}
 function modalTransform(rect){const box=panel.querySelector('.jl-dialog').getBoundingClientRect();return rect&&rect.width&&rect.height?`translate(${rect.left-box.left}px,${rect.top-box.top}px) scale(${rect.width/box.width},${rect.height/box.height})`:'translateY(20px) scale(.96)'}
 function animateModal(opening,rect=modalOrigin){if(reduced.matches)return Promise.resolve();const sheet=panel.querySelector('.jl-dialog'),transform=modalTransform(rect);panel.animate([{backgroundColor:opening?'rgba(31,41,55,0)':'rgba(31,41,55,.42)'},{backgroundColor:opening?'rgba(31,41,55,.42)':'rgba(31,41,55,0)'}],{duration:320,easing:'cubic-bezier(.2,0,0,1)',fill:'forwards'});const motion=sheet.animate(opening?[{transform,opacity:.4},{transform:'none',opacity:1}]:[{transform:'none',opacity:1},{transform,opacity:.3}],{duration:320,easing:'cubic-bezier(.2,0,0,1)',fill:'forwards'});
  // Hidden or throttled pages may never finish an animation; closing must not hang on it.
  return Promise.race([motion.finished.catch(()=>{}),new Promise(resolve=>setTimeout(resolve,420))])}
 function returnControl(){return modalReturn?list.querySelector(`[data-jl="${modalReturn.action}"]${modalReturn.index!==undefined?`[data-index="${modalReturn.index}"]`:''}`):nav.querySelector(`[data-track="${state.track}"]`)}
 function openStep(index=active().step,trigger=document.activeElement){if(modalClosing)return;const p=active();if(!Number.isInteger(index)||index<0||index>5)return;const entering=!state.open,direction=index>=p.step?1:-1;if(entering){overviewScroll=window.scrollY;modalOrigin=trigger?.closest('.jl-overview')?trigger.getBoundingClientRect():null;modalReturn=trigger?.closest('[data-jl]')?{action:trigger.dataset.jl,index:trigger.dataset.index}:null}state.open=true;p.step=index;if(p.step===1&&state.track==='transport'&&!p.ticketSeen.includes(p.mode))p.ticketSeen.push(p.mode);overview.inert=true;document.documentElement.style.overflow='hidden';render({reset:true,motion:!entering,direction});if(entering)animateModal(true)}
 async function close(){if(modalClosing||!state.open)return;modalClosing=true;await animateModal(false,returnControl()?.getBoundingClientRect());state.open=false;overview.inert=false;document.documentElement.style.overflow='';render();window.scrollTo({top:overviewScroll,behavior:'instant'});returnControl()?.focus({preventScroll:true});modalReturn=null;modalClosing=false}
 function next(){const p=active();if(!ready())return;if(p.session){const s=p.session;if(s.index+1<jlGuides[s.id].steps.length){s.index++;render({reset:true,motion:true})}else{p.cases[s.id]=true;p.session=null;render({reset:true,motion:true})}return}
  if(p.step===5){p.saved=true;if(!p.done.includes(5))p.done.push(5);close();return}
  if(!p.done.includes(p.step))p.done.push(p.step);p.step++;p.reached=Math.max(p.reached,p.step);if(p.step===1&&state.track==='transport'&&!p.ticketSeen.includes(p.mode))p.ticketSeen.push(p.mode);render({reset:true,motion:true});
 }
 document.addEventListener('click',async e=>{if(modalClosing)return;const b=e.target.closest('[data-jl]');if(!b||b.disabled||b.type==='checkbox')return;const action=b.dataset.jl,p=state.track==='healthcare'?null:active();
  if(action==='track'){if(state.open)await close();state.track=b.dataset.track;state.open=false;save();renderOverview();window.scrollTo({top:0,behavior:'instant'});if(state.track==='healthcare')updatePhase();return}
  if(action==='open'){openStep(undefined,b);return}if(action==='step'){p.session=null;openStep(+b.dataset.index,b);return}
  if(action==='close'){close();return}if(action==='back'){if(p.session){p.session=null;render({reset:true,motion:true,direction:-1})}else if(p.step>0){p.step--;render({reset:true,motion:true,direction:-1})}else close();return}
  if(action==='language'){const lang=window.appLanguage==='zh'?'en':'zh';try{if(parent!==window&&typeof parent.setAppLanguage==='function'){parent.setAppLanguage(lang);return}}catch{}window.setJourneyLanguage(lang);return}
  if(action==='country'){state.profile.country=b.dataset.value;applyCountry();render();return}
  if(action==='profile'){const field=b.dataset.field;if(['side','habit'].includes(field))state.profile[field]=b.dataset.value;else p[field]=b.dataset.value;if(state.track==='driving')p.licenceStage='';p.applicationStep=0;p.saved=false;render();return}
  if(action==='road-topic'){p.topic=+b.dataset.index;render({motion:true});return}
  if(action==='ticket-mode'){p.mode=b.dataset.value;if(!p.ticketSeen.includes(p.mode))p.ticketSeen.push(p.mode);render({motion:true});return}

  if(action==='case'){const id=b.dataset.id;if(!Object.hasOwn(jlGuides,id))return;p.session={id,index:0,variant:jlGuides[id].variants?.[0]?.id};p.cases[id]=true;render({reset:true,motion:true});return}
  if(action==='licence-grade'){if(Object.hasOwn(jlLicenceGrades,b.dataset.value)){p.licenceStage=b.dataset.value;render({guideMotion:true});if(!reduced.matches)panel.querySelector('.lic-grade-card')?.animate([{opacity:.35,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'ease-out'})}return}
  if(action==='guide-stage'){const index=Number(b.dataset.index);if(p.session&&Number.isInteger(index)&&index>=0&&index<jlGuides[p.session.id].steps.length){p.session.index=index;render({guideMotion:true})}return}
  if(action==='guide-variant'){if(p.session&&jlGuides[p.session.id].variants?.some(v=>v.id===b.dataset.value)){p.session.variant=b.dataset.value;render({guideMotion:true})}return}
  if(action==='campus'){const changed=custom()?.handle(b,p);if(!changed)return;render();const reading=panel.querySelector('.jl-reading');if(!reduced.matches){const target={day:'.mc-stage',spot:'.mc-spot',rhythm:'.mc-compare',arrival:'.mc-keyinfo',level:'.mc-keyinfo',tab:'.mc-compare',pick:'.mc-keyinfo'}[changed];reading.querySelector(target)?.animate([{opacity:.4,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:260,easing:'cubic-bezier(.22,1,.36,1)'});if(changed==='task')panel.querySelector(`[data-field="task"][data-value="${CSS.escape(b.dataset.value)}"] .mc-done-box`)?.animate([{transform:'scale(.6)'},{transform:'scale(1.15)',offset:.6},{transform:'scale(1)'}],{duration:320,easing:'cubic-bezier(.22,1,.36,1)'})}return}
  if(action==='next'){next();return}
  if(action==='other'){await close();state.track=nextTrack();renderOverview();save();window.scrollTo({top:0,behavior:'instant'})}
 });
 nav.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const items=[...nav.querySelectorAll('[role="tab"]')],i=items.indexOf(document.activeElement);if(i<0)return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowRight'?1:-1)+items.length)%items.length;items[n].click();nav.querySelector(`[data-track="${items[n].dataset.track}"]`)?.focus()});
 // Leaving a practice returns to its list; completed situations keep their badges.

 document.addEventListener('change',e=>{const field=e.target.dataset.licenceField;if(!field||state.track!=='driving'||!['age','issuer','experience','earlyIssue','interrupted','stay','learnerPlace'].includes(field))return;const p=active();p[field]=field==='interrupted'?e.target.checked:e.target.value;p.licenceStage='';p.applicationStep=0;p.saved=false;render();panel.querySelector(`[data-licence-field="${field}"]`)?.focus({preventScroll:true})});
 document.addEventListener('toggle',e=>{if(!e.target.isConnected||e.target.dataset.licenceStep===undefined||state.track!=='driving')return;if(e.target.open){active().applicationStep=Number(e.target.dataset.licenceStep);save()}},true);
 document.addEventListener('change',e=>{if(e.target.dataset.jl!=='checklist')return;const p=active(),i=+e.target.dataset.index;p.checks=e.target.checked?[...new Set([...p.checks,i])]:p.checks.filter(n=>n!==i);save();const total=checklist().length,meter=panel.querySelector('.jl-check-progress');if(meter){meter.querySelector('.jl-check-meter span').style.setProperty('--value',p.checks.length/total);meter.querySelector('small').textContent=t(`${p.checks.length} of ${total} done`,`已完成 ${p.checks.length}/${total}`)}panel.querySelector('.jl-footer').innerHTML=footer();if(e.target.checked&&p.checks.length===total&&navigator.vibrate)try{navigator.vibrate([10,40,10])}catch{}});
 document.addEventListener('keydown',e=>{if(!state.open)return;if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const items=[...panel.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),summary')].filter(el=>el.getClientRects().length&&(!el.closest('details:not([open])')||el.matches('summary'))),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 const setLanguage=window.setJourneyLanguage;window.setJourneyLanguage=language=>{setLanguage(language);render({reset:false})};
 window.addEventListener('message',async e=>{if(e.source!==parent||e.data?.type!=='day-one-show-track'||e.data.track!=='healthcare')return;if(state.open)await close();state.track='healthcare';save();renderOverview();window.scrollTo({top:0,behavior:'instant'});updatePhase()});
 window.addEventListener('message',e=>{if(e.source!==parent||e.data?.type!=='day-one-open-learning'||!tracks.includes(e.data.track))return;state.track=e.data.track;const p=active();p.session=null;if(p.saved)p.step=5;openStep()});
 reduced.addEventListener('change',()=>{if(reduced.matches)panel.getAnimations({subtree:true}).forEach(a=>a.cancel())});
 renderOverview();if(state.open&&state.track!=='healthcare'){overview.inert=true;document.documentElement.style.overflow='hidden';renderPanel({reset:true})}
})();
